function holdSeats(seats, seatIds, holdId, now, ttlMs) {
  const isFree = (s) => s && (s.status === "available" ||
                              (s.status === "held" && s.expiresAt <= now));
  const unavailable = seatIds.filter((id) => !isFree(seats.get(id)));
  if (unavailable.length) return { ok: false, unavailable };
  for (const id of seatIds) {
    seats.set(id, { status: "held", holdId, expiresAt: now + ttlMs });
  }
  return { ok: true };
}
```
JS runs this without interruption on one thread. Across many servers, do it in the database as one transaction: `UPDATE seats SET status='held', hold_id=$1, hold_expires_at=now()+interval '10 min' WHERE event_id=$2 AND seat_id = ANY($3) AND (status='available' OR (status='held' AND hold_expires_at < now()))`, then roll back unless the updated row count equals the number of seats.
